do $release$ declare payload jsonb:='{"batch":"description-recovery-20261104","project":"qvplwejffhjvxaypmjut","actions":[{"relation":"catalog_work_descriptions","ref":"description-6272-nl","key":{"work_id":6272,"language":"nl"},"before":null,"after":{"work_id":6272,"language":"nl","bound_author_id":10,"text":"Athena groeit op bij adoptieouders in Beiroet, nadat zij als baby in een Roemeens weeshuis is achtergelaten. Haar belangstelling voor geloof en spiritualiteit brengt haar op een persoonlijke zoektocht. Ze wil haar afkomst begrijpen en haar biologische moeder vinden. Wanneer zij als zieneres naar buiten treedt, roept dat ook weerstand op. Mensen uit haar omgeving vertellen over hun ontmoetingen met haar; samen vormen hun verschillende herinneringen een beeld van haar leven.","source_type":"official_publisher","source_name":"De Arbeiderspers","source_url":"https://www.singeluitgeverijen.nl/de-arbeiderspers/boek/de-heks-van-portobello-2/","evidence":[{"url":"https://www.singeluitgeverijen.nl/de-arbeiderspers/boek/de-heks-van-portobello-2/","role":"content facts; independent original summary","checkedOn":"2026-11-04"},{"url":"https://www.bibliotheek.nl/catalogus/titel.405341350.html/de-heks-van-portobello/","role":"exact edition identity/ISBN/language","isbn13":"9789029564731","checkedOn":"2026-11-04"},{"url":"https://openlibrary.org/works/OL26176645W","role":"cross-check Work and source-edition parent"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-04T20:00:00+00:00","review_batch":"description-recovery-20261104"}},{"relation":"catalog_work_descriptions","ref":"description-1995-en","key":{"work_id":1995,"language":"en"},"before":null,"after":{"work_id":1995,"language":"en","bound_author_id":125,"text":"Celaena Sardothien has become the King’s Champion, but serving him puts her conscience under pressure. She conceals her real loyalties while carrying out a dangerous role at court. Her search for answers draws her friends into conflicts that are difficult to understand and harder to escape. As suspicion spreads around her, she must decide whom to trust and what she is willing to defend. This is the second novel in the Throne of Glass series.","source_type":"official_publisher","source_name":"Bloomsbury","source_url":"https://www.bloomsbury.com/media/gq5hkjjn/badult-w23-catalog.pdf","evidence":[{"url":"https://www.bloomsbury.com/media/gq5hkjjn/badult-w23-catalog.pdf","role":"content facts; independent original summary","checkedOn":"2026-11-04","page":22},{"url":"https://catalog.dmpl.org/Record/223098","role":"exact edition identity/ISBN/language","isbn13":"9781619630628","checkedOn":"2026-11-04"},{"url":"https://openlibrary.org/works/OL16809980W","role":"cross-check Work and source-edition parent"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-04T20:00:00+00:00","review_batch":"description-recovery-20261104"}},{"relation":"catalog_work_descriptions","ref":"description-1824-en","key":{"work_id":1824,"language":"en"},"before":null,"after":{"work_id":1824,"language":"en","bound_author_id":129,"text":"A man known as K. arrives in a village expecting to work as a land surveyor for the authorities in a nearby castle. Reaching those authorities proves unexpectedly difficult. Messages, intermediaries and encounters with the villagers complicate his efforts to establish his position. The more he tries to understand the rules governing the place, the less secure his situation becomes. Kafka follows his struggle to gain recognition from a distant and elusive power.","source_type":"official_publisher","source_name":"Penguin Random House / Everyman’s Library","source_url":"https://penguinrandomhousehighereducation.com/book/?isbn=9780679417354","evidence":[{"url":"https://penguinrandomhousehighereducation.com/book/?isbn=9780679417354","role":"content facts; independent original summary","checkedOn":"2026-11-04"},{"url":"https://openlibrary.org/books/OL7698685M","role":"exact edition identity/ISBN/language","isbn13":"9780679417354","checkedOn":"2026-11-04"},{"url":"https://openlibrary.org/works/OL498434W","role":"cross-check Work and source-edition parent"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-04T20:00:00+00:00","review_batch":"description-recovery-20261104"}},{"relation":"catalog_work_descriptions","ref":"description-8783-en","key":{"work_id":8783,"language":"en"},"before":null,"after":{"work_id":8783,"language":"en","bound_author_id":5216,"text":"Skye O’Malley builds a life that takes her far beyond her Irish beginnings. Love, family and the demands of a shipping enterprise pull her into dangerous conflicts. Her journeys carry her to Algiers and London, where private ambitions meet the power of the English crown. Skye’s determination brings her into opposition with Queen Elizabeth I. This historical romance follows her attempts to protect the people and independence she values while pursuing a future of her own.","source_type":"official_publisher","source_name":"Penguin Random House / Ballantine Books","source_url":"https://www.penguinrandomhouse.com/books/168589/skye-omalley-by-bertrice-small/","evidence":[{"url":"https://www.penguinrandomhouse.com/books/168589/skye-omalley-by-bertrice-small/","role":"content facts; independent original summary","checkedOn":"2026-11-04"},{"url":"https://openlibrary.org/books/OL10683537M","role":"exact edition identity/ISBN/language","isbn13":"9780345292568","checkedOn":"2026-11-04"},{"url":"https://openlibrary.org/works/OL1692389W","role":"cross-check Work and source-edition parent"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-04T20:00:00+00:00","review_batch":"description-recovery-20261104"}}],"bindings":[{"work":{"id":6272,"title":"De heks van Portobello","cover_id":null,"subjects":null,"subtitle":null,"author_id":10,"work_type":null,"created_at